\begin{definition}[Version of a function]
\label{def:version-of-a-function}
\dcref{ch5:5.6-def-2}
\group{Sobolev Inequalities}
We say $u^*$ is a version of a given function $u$ provided
$$u = u^* \text{ a.e.}$$
\end{definition}

